package com.orderflow.delivery.service;import com.orderflow.events.EventMetadata;import java.sql.Timestamp;import java.time.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class ProcessedEventStore{private final JdbcTemplate jdbc;private final Clock clock;public ProcessedEventStore(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}public boolean contains(EventMetadata m,String consumer){Integer n=jdbc.queryForObject("SELECT count(*) FROM processed_event WHERE event_id=? AND consumer_name=?",Integer.class,m.eventId(),consumer);return n!=null&&n>0;}public void add(EventMetadata m,String consumer){jdbc.update("INSERT INTO processed_event(event_id,event_type,aggregate_id,consumer_name,processed_at,correlation_id) VALUES(?,?,?,?,?,?)",m.eventId(),m.eventType().name(),m.aggregateId(),consumer,Timestamp.from(Instant.now(clock)),m.correlationId());}}
